/bin/zsh -lc "MPLCONFIGDIR=/tmp/brainx-alpha-mpl python - <<'PY'
import brainmass
import brainunit as u

candidates = {
    'b': 50.0 * u.Hz,
    'C4': 0.25,
    'Hi': 22.0 * u.mV,
    'H_i': 22.0 * u.mV,
    'A_i': 22.0 * u.mV,
}
for name, value in candidates.items():
    try:
        brainmass.JansenRitStep(in_size=1, **{name: value})
    except Exception as exc:
        print(name, 'rejected:', type(exc).__name__, str(exc).splitlines()[0])
    else:
        print(name, 'accepted')
PY"

