/bin/zsh -lc "MPLCONFIGDIR=/tmp/brainx-alpha-mpl python - <<'PY'
import brainmass, brainstate, brainunit as u
import jax.numpy as jnp

DT=.1*u.ms
for form in ('two','tuple','none'):
 m=brainmass.WilsonCowanStep(1,tau_E=15*u.ms,tau_I=22.5*u.ms,wEE=16.,wEI=12.,wIE=15.,wII=3.)
 with brainstate.environ.context(dt=DT):
  m.init_all_states()
  try:
   if form=='two': y=m.update(1.0,0.0)
   elif form=='tuple': y=m.update((1.0,0.0))
   else: y=m.update()
   print(form, 'ok', type(y), y, m.rE.value, m.rI.value)
  except Exception as exc: print(form,'failed',type(exc).__name__,exc)
PY"

